/bin/bash -c "python3 - <<'PY'

def eta(a,b):
 if b<a:return 1-b/a
 if b>a:return 1-(1-b)/(1-a)
 return 0.

def urow(a,b,wa,wb):
 return min(wb*eta(a,b),wa*eta(b,a))
# Inputs from the manuscript's Figure 2.
points=[]
for i in range(801):
 x0=2/7+(3/7)*i/800
 n0=max(0.,-2/3+(7/3)*x0)
 for j in range(801):
  x1=j/800
  n1=(3/7)*x1
  er=.7*x0-.1+.3*x1
  if er>.251:continue
  u=urow(x0,x1,.35,.15)+urow(n0,n1,.15,.35)
  points.append((u,er,x0,x1))
for beta in [.25,.5,.6,.7,.75,.8,.9,1.]:
 p=min(points,key=lambda p:beta*p[0]+(1-beta)*p[1])
 print('beta',beta,'u,error,FPR0,FPR1',p)
for limit in [.12,.15,.18,.2,.23]:
 p=min((p for p in points if p[1]<=limit+1e-10),key=lambda p:p[0])
 print('error cap',limit,'constrained solution',p)
PY"
